function resolveUrl(href, base) {
  const origin = base.protocol + '://' + base.hostname + (base.port ? ':' + base.port : '');
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return base.protocol + ':' + href;
